        onsiteAttributedData.foreach(row -> {
            String query = row.getAs("query");
            long timestamp = row.getAs("timestamp");

            if (topFrequentQueries.contains(query)) {
                if (!isCacheHit(query, timestamp)) {
                    cacheMiss(query, timestamp);
                }
            }
        });

        DataFrame hitRateDataFrame = getHitRateDataFrame(spark, cache);
        hitRateDataFrame.show();
