First, we will create a `TooltipContext` to store the state of the currently opened Tooltip and a function to close it.

```jsx
import React, { createContext, useContext, useState } from 'react';

const TooltipContext = createContext();

export const TooltipProvider = ({ children }) => {
  const [tooltip, setTooltip] = useState(null);

  const closeTooltip = () => {
    setTooltip(null);
  };

  return (
    <TooltipContext.Provider value={{ tooltip, closeTooltip }}>
      {children}
    </TooltipContext.Provider>
  );
};

export const useTooltip = () => useContext(TooltipContext);
```

Now, we can create the Tooltip component that uses the `TooltipProvider` and `useTooltip` hook to manage the state and close the previously opened Tooltip when a new one is opened.

```jsx
import React, { useEffect } from 'react';
import { Tooltip as ReactTooltip } from 'react-tooltip';
import 'react-tooltip/dist/react-tooltip.css';
import { useTooltip } from './TooltipContext';

const Tooltip = ({ children, id, content }) => {
  const { tooltip, closeTooltip } = useTooltip();

  useEffect(() => {
    if (tooltip && tooltip.id !== id) {
      closeTooltip();
    }
  }, [tooltip, id, closeTooltip]);

  return (
    <>
      {children}
      <ReactTooltip id={id} place="bottom" effect="solid">
        {content}
      </ReactTooltip>
    </>
  );
};

export default Tooltip;
```

