```

3. Use the following code to fetch the exchange rate and convert the price:

```javascript
const axios = require('axios');

async function getExchangeRate(baseCurrency, targetCurrency) {
  const response = await axios.get(`https://openexchangerates.org/api/latest.json?app_id=YOUR_API_KEY`);
  const rates = response.data.rates;
  return rates[targetCurrency] / rates[baseCurrency];
}

async function convertPrice(price, baseCurrency, targetCurrency) {
  const exchangeRate = await getExchangeRate(baseCurrency, targetCurrency);
  return price * exchangeRate;
}

