Here's a simple function that calculates the elapsed time in seconds since a post was made, given the post's timestamp in the format `YYYY-MM-DDTHH:mm:ssZ`.

```typescript
import moment from 'moment-timezone';

function elapsedTimeSincePost(postTimestamp: string): number {
  const post = moment.tz(postTimestamp, 'YYYY-MM-DDTHH:mm:ssZ');
  const now = moment.tz('America/Los_Angeles');
  const elapsed = now.diff(post, 'seconds');

  return elapsed;
}
```

