package main

import (
	"fmt"
	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/cognitoidentityprovider"
)

func main() {
	sess := session.Must(session.NewSession(&aws.Config{
		Region: aws.String("us-east-2"),
	}))

	svc := cognitoidentityprovider.New(sess)

	input := &cognitoidentityprovider.ListUsersInGroupInput{
		UserPoolId: aws.String("us-east-2_4YtYz6hV0"),
		GroupName:  aws.String("account:6412003a7a61c0beecdd16a7"),
	}

	result, err := svc.ListUsersInGroup(input)
	if err != nil {
		fmt.Println(err)
		return
	}

	var userAttributes []map[string]string

	for _, user := range result.Users {
		if user.Attributes != nil {
			if containsValue(user.Attributes, "1", "custom:profileType") || containsValue(user.Attributes, "2", "custom:profileType") {
				userAttributes = append(userAttributes, user.Attributes)
			}
		}
	}

	for _, userAttribute := range userAttributes {
		for key, value := range userAttribute {
			fmt.Println(key, value)
		}
	}
}

func containsValue(slice []map[string]string, value string, key string) bool {
	for _, item := range slice {
		if item[key] == value {
			return true
		}
	}
	return false
}
